        self.parts = parts
        self.n = 0
        for p in parts:
            self.n += p.n

    def fp_range(self, lo, hi):
        if hi <= lo:
            return 0, 0
        n = 0
        h = 0
        off = 0
        for p in self.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            a = max(lo, p0) - p0
            b = min(hi, p1) - p0
            pn, ph = p.fp_range(a, b)
            n, h = _combine(n, h, pn, ph)
        return n, h

    def window(self, lo, hi):
        out = bytearray()
        off = 0
        for p in self.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            a = max(lo, p0) - p0
            b = min(hi, p1) - p0
            out += p.window(a, b)
        return bytes(out)


class Rep(Seq):
    __slots__ = ('unit', 'count', '_table')

    def __init__(self, unit, count):
        self.unit = unit
        self.count = count
        self.n = unit.n * count
        table = [unit.fp()]
        k = 1
        while (1 << k) <= count:
            hp, lp = table[-1]
            hn, ln = _combine(lp, hp, lp, hp)
            table.append((hn, ln))
            k += 1
        self._table = table

    def _unit_pow(self, m):
        n = 0
        h = 0
        k = 0
        while m:
            if m & 1:
                hk, lk = self._table[k]
                n, h = _combine(n, h, lk, hk)
            m >>= 1
            k += 1
        return n, h

    def fp_range(self, lo, hi):
        if hi <= lo:
            return 0, 0
        L = self.unit.n
        n = 0
        h = 0
        x = lo
        while x < hi:
            o = x % L
            if o == 0:
                m = (hi - x) // L
                if m:
                    pn, ph = self._unit_pow(m)
                    n, h = _combine(n, h, pn, ph)
                    x += m * L
                    continue
            take = min(L - o, hi - x)
            pn, ph = self.unit.fp_range(o, o + take)
            n, h = _combine(n, h, pn, ph)
            x += take
        return n, h

    def window(self, lo, hi):
        L = self.unit.n
        out = bytearray()
        x = lo
        while x < hi:
            o = x % L
            if o == 0:
                m = (hi - x) // L
                if m:
                    out += self.unit.window(0, L) * m
                    x += m * L
                    continue
            take = min(L - o, hi - x)
            out += self.unit.window(o, o + take)
            x += take
        return bytes(out)


_EMPTY = Lit(b'')


def literal(data):
    if data is None:
        return _EMPTY
    if type(data) is not bytes:
        raise ValueError('literal bytes')
    return Lit(data) if data else _EMPTY


def size(node):
    return node.n if node is not None else 0


def _cat_many(parts):
    good = [p for p in parts if p.n]
    if not good:
        return _EMPTY
    if len(good) == 1:
        return good[0]
    return Cat(good)


def concat(a, b):
    if a is None or a.n == 0:
        return b if b is not None else _EMPTY
    if b is None or b.n == 0:
        return a
    parts = []
    if isinstance(a, Cat):
        parts.extend(a.parts)
    else:
        parts.append(a)
    if isinstance(b, Cat):
        parts.extend(b.parts)
    else:
        parts.append(b)
    return Cat(parts)


def repeat(node, count):
    if node is None:
        node = _EMPTY
    if type(count) is not int or isinstance(count, bool) or count < 0:
        raise ValueError('repeat count')
    if count == 0 or node.n == 0:
        return _EMPTY
    if isinstance(node, Rep):
        unit = node.unit
        total = node.count * count
    else:
        unit = node
        total = count
    if unit.n * total > MAX:
        raise ValueError('sequence length')
    return Rep(unit, total)


def cut(node, lo, hi):
    if node is None:
        node = _EMPTY
    if type(lo) is not int or type(hi) is not int:
        raise ValueError('slice bounds')
    if not 0 <= lo <= hi <= node.n:
        raise ValueError('slice bounds')
    if lo == 0 and hi == node.n:
        return node
    if lo == hi:
        return _EMPTY
    if isinstance(node, Lit):
        return Lit(node.data[lo:hi])
    if isinstance(node, Cat):
        parts = []
        off = 0
        for p in node.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            piece = cut(p, max(lo, p0) - p0, min(hi, p1) - p0)
            if piece.n:
                parts.append(piece)
        return _cat_many(parts)
    L = node.unit.n
    parts = []
    x = lo
    while x < hi:
        o = x % L
        if o == 0:
            m = (hi - x) // L
            if m:
                parts.append(Rep(node.unit, m))
                x += m * L
                continue
        take = min(L - o, hi - x)
        piece = cut(node.unit, o, o + take)
        if piece.n:
            parts.append(piece)
        x += take
    return _cat_many(parts)


def materialize(node, limit=65536):
    if node is None:
        return b''
    if node.n > limit:
        raise ValueError('bounded materialization')
    return node.window(0, node.n)


def fingerprint(node):
    if node is None:
        n, h = 0, 0
    else:
        n, h = node.fp()
    return {'n': n, 'h': format(h, '016x')}


def fp_bytes(data):
    return {'n': len(data), 'h': format(_hash(data), '016x')}


def next_lf(node, start=0, window=8194):
    """Index of the first LF at or after start within the window, else -1."""
    if node is None:
        return -1
    end = min(start + window, node.n)
    pos = start
    while pos < end:
        chunk = node.window(pos, min(pos + 4096, end))
        k = chunk.find(b'\n')
        if k >= 0:
            return pos + k
        pos += len(chunk)
    return -1


