# Expression evaluation and templates


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.env = {}
        seen = set()
        for row in definitions:
            name, src = row
            if type(name) is not str or not _NAME.fullmatch(name) or keyword.iskeyword(name):
                raise ValueError('definition name')
            if name in seen:
                raise ValueError('definition name')
            seen.add(name)
            if type(src) is not str or len(src) > EXPRESSION_LIMIT:
                raise ValueError('expression source')
            self.env[name] = self.expression(src)

    # -- expressions -------------------------------------------------------
    def expression(self, text):
        try:
            tree = ast.parse(text, mode='eval')
        except SyntaxError:
            raise ValueError('expression syntax') from None
        body = tree.body
        self._check_depth(body)
        value = self._eval(body)
        if not isinstance(value, Seq):
            raise ValueError('expression result')
        return value

    @staticmethod
    def _check_depth(root):
        stack = [(root, 0)]
        while stack:
            node, depth = stack.pop()
            if depth > MAX_DEPTH:
                raise ValueError('expression depth')
            for child in ast.iter_child_nodes(node):
                stack.append((child, depth + 1))

    def _eval(self, node):
        if isinstance(node, ast.Constant):
            v = node.value
            if type(v) is str:
                return Lit(v.encode('utf8'))
            if type(v) is bytes:
                return Lit(v) if v else _EMPTY
            if type(v) is int:
                if 0 <= v <= MAX:
                    return v
                raise ValueError('integer literal')
            raise ValueError('constant type')
        if isinstance(node, ast.Name):
            if node.id in self.env:
                return self.env[node.id]
            raise ValueError('unknown name')
        if isinstance(node, ast.BinOp):
            if isinstance(node.op, ast.Add):
                a = self._eval(node.left)
                b = self._eval(node.right)
                if isinstance(a, Seq) and isinstance(b, Seq):
                    return concat(a, b)
                raise ValueError('concatenation types')
            if isinstance(node.op, ast.Mult):
                a = self._eval(node.left)
                b = self._eval(node.right)
                if isinstance(a, Seq) and type(b) is int:
                    return repeat(a, b)
                if type(a) is int and isinstance(b, Seq):
                    return repeat(b, a)
                raise ValueError('repetition types')
            raise ValueError('operator')
        if isinstance(node, ast.Subscript):
            value = self._eval(node.value)
            if not isinstance(value, Seq):
                raise ValueError('slice target')
            sl = node.slice
            if not isinstance(sl, ast.Slice):
                raise ValueError('index')
            if sl.step is not None:
                if not (isinstance(sl.step, ast.Constant) and sl.step.value is None):
                    raise ValueError('slice step')
            lo = self._bound(sl.lower, 0)
            hi = self._bound(sl.upper, value.n)
            if not 0 <= lo <= hi <= value.n:
                raise ValueError('slice bounds')
            return cut(value, lo, hi)
        raise ValueError('unsupported syntax')

    @staticmethod
    def _bound(node, default):
        if node is None:
            return default
        if isinstance(node, ast.Constant) and type(node.value) is int:
            return node.value
        raise ValueError('slice endpoint')

    # -- templates ---------------------------------------------------------
    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        if len(value) >= 4 and value.startswith('{{') and value.endswith('}}'):
            src = value[2:-2].strip()
            if len(src) > EXPRESSION_LIMIT:
                raise ValueError('expression source')
            return self.expression(src)
        if len(value) > TEMPLATE_LIMIT:
            raise ValueError('template source')
        if _MARKER not in value:
            return Lit(value.encode('utf8')) if value else _EMPTY
        out = []
        rest = value
        occurrence = 0
        while True:
            k = rest.find(_MARKER)
            if k < 0:
                out.append(rest)
                break
            out.append(rest[:k])
            out.append(self._random(coordinate, occurrence))
            occurrence += 1
            rest = rest[k + len(_MARKER):]
        return Lit(''.join(out).encode('utf8'))

    def _random(self, coordinate, occurrence):
        source = f'{self.seed}/{coordinate}/{occurrence}'.encode('utf8')
        return hashlib.sha256(source).hexdigest()[:20]
