HEADER_LINE = re.compile(_TOKEN_CHARS + rb"+:[\t\x20-\x7e]*\Z")
CHUNK_LINE = re.compile(rb"[0-9A-Fa-f]+(?:;[\t\x20-\x7e]*)?\Z")

