        for _label, node in parts:
            self.starts.append(off)
            off += node.size()
        self.n = off

    def _index(self, pos):
        return bisect.bisect_right(self.starts, pos) - 1

    def window(self, pos, count):
        end = min(pos + count, self.n)
        if pos >= end:
            return b''
        out = bytearray()
