    return h


def _fp_bytes(data):
    return {'n': len(data), 'h': format(_hash(data), '016x')}


def _encode_pairs(pairs):
    out = bytearray(len(pairs).to_bytes(8, 'big'))
    for name, value in pairs:
        out += len(name).to_bytes(8, 'big') + name
        out += len(value).to_bytes(8, 'big') + value
    return bytes(out)


def _read_line(stream, pos):
    """Return (content, span) for the CRLF-terminated line at pos."""
    avail = stream.n - pos
    data = stream.window(pos, min(avail, LINE_WINDOW))
    lf = data.find(b'\n')
    if lf < 0:
        if avail > LINE_LIMIT + 1:
            raise _Syntax()
        raise _Incomplete()
    if lf == 0 or data[lf - 1] != 0x0d:
        raise _Syntax()
    return data[:lf - 1], lf + 1


def _parse_request(stream, pos, budget):
    """Frame one request; return (record, end).  Raises _Syntax/_Incomplete."""
    content, span = _read_line(stream, pos)
    match = REQUEST_LINE.fullmatch(content)
    if match is None:
        raise _Syntax()
    method = content[:content.index(b' ')]
    target = match.group(1)
    block = span
    fields_count = 0
    line_pos = pos + span
    headers = []
    while True:
        content, span = _read_line(stream, line_pos)
        block += span
        if block > BLOCK_LIMIT:
            raise _Syntax()
        line_pos += span
        if not content:
            break
        if HEADER_LINE.fullmatch(content) is None:
            raise _Syntax()
        fields_count += 1
        if fields_count > FIELD_LIMIT:
            raise _Syntax()
        colon = content.index(b':')
        headers.append((content[:colon], _trim(content[colon + 1:])))

    # Field framing rules.
    content_lengths = []
    transfer_encodings = []
    for name, value in headers:
        folded = name.lower()
        if folded == b'content-length':
            content_lengths.append(value)
        elif folded == b'transfer-encoding':
            transfer_encodings.append(value)

    framing = 'none'
    length = 0
    if transfer_encodings:
        if len(transfer_encodings) != 1 or content_lengths:
            raise _Syntax()
        if _trim(transfer_encodings[0]).lower() != b'chunked':
            raise _Syntax()
        framing = 'chunked'
    elif content_lengths:
        values = set()
        for value in content_lengths:
            members = value.split(b',')
            for member in members:
                member = _trim(member)
                if not member or not member.isdigit():
                    raise _Syntax()
                number = int(member)
                if number > MAX:
                    raise _Syntax()
                values.add(number)
        if len(values) != 1:
            raise _Syntax()
        length = values.pop()
        framing = 'length'

    hosts = [value for name, value in headers if name.lower() == b'host']
    host_count = len(hosts)

    body_fp = (0, 0)
    trailers = []
    if framing == 'length':
        end = line_pos + length
        if stream.n < end:
            raise _Incomplete()
        body_fp = stream.fp_range(line_pos, end)
    elif framing == 'none':
        end = line_pos
    else:
        chunk_pos = line_pos
        while True:
            content, span = _read_line(stream, chunk_pos)
            budget[1] += 1
            if budget[1] > MAX_CHUNK_LINES:
                raise ValueError('chunk line budget')
            chunk_pos += span
            if CHUNK_LINE.fullmatch(content) is None:
                raise _Syntax()
            digits = content.split(b';', 1)[0]
            number = int(digits, 16)
            if number > MAX:
                raise _Syntax()
            if number == 0:
                break
            if stream.n < chunk_pos + number + 2:
                raise _Incomplete()
            body_fp = _combine_fp(body_fp, stream.fp_range(chunk_pos, chunk_pos + number))
            if stream.window(chunk_pos + number, 2) != CRLF:
                raise _Syntax()
            chunk_pos += number + 2
        tblock = 0
        tfields = 0
        while True:
            content, span = _read_line(stream, chunk_pos)
            tblock += span
            if tblock > BLOCK_LIMIT:
                raise _Syntax()
            chunk_pos += span
            if not content:
                break
            if HEADER_LINE.fullmatch(content) is None:
                raise _Syntax()
            tfields += 1
            if tfields > FIELD_LIMIT:
                raise _Syntax()
            colon = content.index(b':')
            name = content[:colon]
            if name.lower() in TRAILER_FORBIDDEN:
                raise _Syntax()
            trailers.append((name, _trim(content[colon + 1:])))
        end = chunk_pos

    return {
        'start': pos,
        'end': end,
        'method': _fp_bytes(method),
        'target': _fp_bytes(target),
        'host': _fp_bytes(_trim(hosts[0]).lower()) if host_count == 1 else {'n': 0, 'h': '0'*16},
        'host_count': host_count,
        'headers': _fp_bytes(_encode_pairs(headers)),
        'body': _fp(body_fp),
        'trailers': _fp_bytes(_encode_pairs(trailers)),
        'framing': framing,
        '_host_folded': _trim(hosts[0]).lower() if host_count == 1 else None,
    }, end


def _combine_fp(a, b):
    if b[0] == 0:
        return a
    if a[0] == 0:
        return b
    return a[0] + b[0], (a[1] * pow(257, b[0], 1 << 64) + b[1]) & ((1 << 64) - 1)


def _mismatch(record, expect):
    if record['method'] != _fp_bytes(expect['method']):
        return True
    if record['target'] != _fp_bytes(expect['target']):
        return True
    if record['host_count'] != 1:
        return True
    return record['_host_folded'] != expect['host'].lower()


def audit_channels(channels, cases, sent):
    """Audit origin captures; patch each case record with origin_count and flags.

    Returns the channel records in input order.
    """
    expects = {case['name']: case['expect'] for case in cases}
    request_frames = {row['name']: row['request_frames'] for row in sent}
    budget = [0, 0]
    owner_counts = {}
    owned = {name: [] for name in expects}
    channel_records = []
    for channel in channels:
        stream = Stream([(part['case'], part['data']) for part in channel['parts']])
        prefix = []
        off = 0
        for part in channel['parts']:
            off += part['data'].size()
            prefix.append(off)
        records = []
        error = None
        pos = 0
        while pos < stream.n:
            req_start = pos
            try:
                record, end = _parse_request(stream, pos, budget)
            except _Syntax:
                error = {'kind': 'syntax', 'offset': req_start}
                break
            except _Incomplete:
                error = {'kind': 'incomplete', 'offset': req_start}
                break
            budget[0] += 1
            if budget[0] > MAX_REQUESTS:
                raise ValueError('request budget')
            owner = stream.owner_at(req_start)
            owners = stream.owners(req_start, end)
            record['owner'] = owner
            record['owners'] = owners
            extra = False
            if owner is not None:
                owner_counts[owner] = owner_counts.get(owner, 0) + 1
                extra = owner_counts[owner] > 1
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if len(owners) > 1:
                flags.add('mixed_owner')
            if record['host_count'] == 0:
                flags.add('missing_host')
            elif record['host_count'] > 1:
                flags.add('multiple_host')
            if owner is not None:
                if _mismatch(record, expects[owner]):
                    flags.add('identity')
                if extra:
                    flags.add('extra')
                if request_frames[owner] == 0:
                    flags.add('unsent')
            record['flags'] = sorted(flags)
            del record['_host_folded']
            records.append(record)
            if owner is not None:
                owned[owner].append(record)
            pos = end
        committed = [sum(1 for r in records if r['end'] <= mark) for mark in prefix]
        channel_records.append({
            'name': channel['name'],
            'bytes': _fp(stream.fp_range(0, stream.n)),
            'requests': records,
            'committed': committed,
            'error': error,
        })
    for row in sent:
        name = row['name']
        reqs = owned.get(name, [])
        origin_count = len(reqs)
        flags = set()
        if row['request_frames'] > 0 and origin_count == 0:
            flags.add('missing_origin')
        if origin_count > 1:
            flags.add('extra_origin')
        if origin_count > 0 and row['request_frames'] == 0:
            flags.add('unsent_origin')
        if any('identity' in r['flags'] for r in reqs):
            flags.add('identity')
        if any('mixed_owner' in r['flags'] for r in reqs):
            flags.add('mixed_origin')
        row['origin_count'] = origin_count
        row['flags'] = sorted(flags)
    return channel_records
