"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import math
from pathlib import Path
import re
import sys

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context,MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels,TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)
SEED_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-'
STDIN_LIMIT = 8*1024**2


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=65536):
    if type(value) is not str or (maximum is not None and len(value)>maximum):
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def compile_document(document):
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if any(c not in SEED_CHARS for c in seed):
        raise ValueError('seed')
    definitions = sequence(document['definitions'],8192)
    for row in definitions:
        if type(row) is not list or len(row)!=2:
            raise ValueError('definition pair')
        text(row[0],32)
        text(row[1],8192)
    context = Context(definitions,seed)
    timeout = integer(document['timeout_ms'],1,10**9)
    cases = sequence(document['cases'],2000)
    names = set()
    validated = []
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],50000)
        exp = case['expect']
        exact(exp,['method','target','host'])
        expect = {}
        for key in ('method','target','host'):
            value = text(exp[key],8192).encode('ascii')
            if not value or not all(33 <= c <= 126 for c in value):
                raise ValueError('expected identity')
            expect[key] = value
        if TOKEN.fullmatch(expect['method']) is None:
            raise ValueError('expected method')
        validated.append({'name':name,'frames':frames,'expect':expect})
    payload,pause_totals,frame_pairs = compile_cases(validated,context)
    budget = sum(len(case['frames']) for case in validated)
    for case in validated:
        if pause_totals[case['name']]+timeout > MAX:
            raise ValueError('time overflow')
    records = sequence(document['events'],50000)
    budget += len(records)
    events = []
    event_pairs = 0
    for index,record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        if kind == 'close':
            exact(record,['at','kind'])
            events.append({'at':integer(record['at']),'kind':'close'})
        elif kind == 'headers':
            exact(record,['at','kind','stream','end','fields'])
            at = integer(record['at'])
            stream = integer(record['stream'],0,(1 << 32)-1)
            if type(record['end']) is not bool:
                raise ValueError('event end')
            raw_fields = sequence(record['fields'],128)
            fields = []
            for k,field in enumerate(raw_fields):
                if type(field) is not list or len(field)!=2:
                    raise ValueError('event field pair')
                fields.append((context.template(text(field[0],None),f'event/{index}/h/{k}/n'),
                               context.template(text(field[1],None),f'event/{index}/h/{k}/v')))
            event_pairs += len(raw_fields)
            events.append({'at':at,'kind':'headers','stream':stream,
                           'fields':fields,'end':record['end']})
        elif kind == 'data':
            exact(record,['at','kind','stream','end','data'])
            at = integer(record['at'])
            stream = integer(record['stream'],0,(1 << 32)-1)
            if type(record['end']) is not bool:
                raise ValueError('event end')
            data = context.template(text(record['data'],None),f'event/{index}/data')
            events.append({'at':at,'kind':'data','stream':stream,
                           'data':data,'end':record['end']})
        else:
            raise ValueError('event kind')
    channels = sequence(document['channels'],256)
    channel_names = set()
    compiled_channels = []
    for index,channel in enumerate(channels):
        exact(channel,['name','parts'])
        name = text(channel['name'],32)
        if not NAME.fullmatch(name) or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'],50000)
        budget += len(parts)
        out_parts = []
        for j,part in enumerate(parts):
            exact(part,['case','data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            data = context.template(text(part['data'],None),f'channel/{index}/part/{j}/data')
            out_parts.append({'case':owner,'data':data})
        compiled_channels.append({'name':name,'parts':out_parts})
    if budget>50000 or frame_pairs+event_pairs>32768:
        raise ValueError('combined budget')
    return {'cases':validated,'payload':payload,'events':events,
            'channels':compiled_channels,'timeout':timeout}


def run(document):
    spec = compile_document(document)
    fuzzer = FuzzExecutor()
    sent = fuzzer.send_payload(spec['payload'],spec['events'],spec['timeout'])
    origin = audit_channels(spec['channels'],spec['cases'],sent)
    return {'cases':sent,'channels':origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(STDIN_LIMIT+1)
        if len(raw)>STDIN_LIMIT:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'),object_pairs_hook=pairs,
                              parse_constant=bad_constant,parse_float=finite_float)
        result = run(document)
    except (ValueError,TypeError,KeyError,IndexError,UnicodeError,
            RecursionError,OverflowError):
        result = {'error':'input'}
    encoded=json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded+b'\n')


if __name__=='__main__':main()
